-- Affiliate program schema for HubinBD. This mirrors the live migration add_admin_control_and_affiliate_foundation.
-- RLS is enabled for every exposed affiliate and audit table. See Supabase migration history for policy definitions.
create table if not exists public.affiliate_profiles (id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,affiliate_code text not null unique,display_name text not null,phone text,status text not null default 'pending' check(status in ('pending','approved','rejected','suspended')),payout_method text,payout_account text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.affiliate_clicks (id bigint generated by default as identity primary key,affiliate_id uuid not null references public.affiliate_profiles(id) on delete cascade,landing_path text not null default '/',clicked_at timestamptz not null default now());
create table if not exists public.affiliate_commission_rules (id uuid primary key default gen_random_uuid(),category_id bigint references public.categories(id) on delete set null,rule_name text not null,commission_rate numeric(5,2) not null default 0 check(commission_rate between 0 and 100),is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.affiliate_settings (id boolean primary key default true check(id=true),program_enabled boolean not null default false,default_commission_rate numeric(5,2) not null default 0 check(default_commission_rate between 0 and 100),cookie_days integer not null default 30 check(cookie_days between 1 and 90),minimum_payout numeric(12,2) not null default 500,attribution_model text not null default 'last_click' check(attribution_model in ('last_click','first_click')),updated_at timestamptz not null default now());
create table if not exists public.affiliate_commissions (id uuid primary key default gen_random_uuid(),affiliate_id uuid not null references public.affiliate_profiles(id) on delete restrict,order_id uuid not null unique references public.orders(id) on delete restrict,order_amount numeric(12,2) not null check(order_amount>=0),commission_rate numeric(5,2) not null check(commission_rate between 0 and 100),commission_amount numeric(12,2) not null check(commission_amount>=0),status text not null default 'pending' check(status in ('pending','approved','rejected','paid','reversed')),created_at timestamptz not null default now(),processed_at timestamptz,processed_by uuid references auth.users(id));
create table if not exists public.affiliate_payout_requests (id uuid primary key default gen_random_uuid(),affiliate_id uuid not null references public.affiliate_profiles(id) on delete restrict,amount numeric(12,2) not null check(amount>0),payout_method text not null,payout_account text not null,status text not null default 'pending' check(status in ('pending','approved','paid','rejected')),admin_note text,requested_at timestamptz not null default now(),processed_at timestamptz,processed_by uuid references auth.users(id));
create table if not exists public.admin_audit_logs (id bigint generated by default as identity primary key,actor_id uuid references auth.users(id),action text not null,target_table text not null,target_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.orders add column if not exists affiliate_id uuid references public.affiliate_profiles(id) on delete set null;
alter table public.orders add column if not exists affiliate_code text;
alter table public.orders add column if not exists affiliate_attributed_at timestamptz;
alter table public.orders add column if not exists product_id bigint references public.products(id) on delete set null;

-- Runtime hardening and configured defaults (applied to project database).
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to anon, authenticated;
insert into public.affiliate_settings(id,program_enabled,default_commission_rate,cookie_days,minimum_payout,attribution_model,updated_at)
values(true,false,5,30,500,'last_click',now())
on conflict(id) do update set default_commission_rate=5,cookie_days=30,minimum_payout=500,attribution_model='last_click',updated_at=now();
-- Runtime RPCs and triggers are installed directly in the connected project.
-- Public reads only the non-sensitive settings row; writes remain admin-only.
drop policy if exists "affiliate settings public read" on public.affiliate_settings;
create policy "affiliate settings public read" on public.affiliate_settings for select to anon, authenticated using(id=true);
